SELECT x.employee_id,e.name,x.latest_rating-x.earliest_rating AS improvement_score FROM (SELECT employee_id,MAX(CASE WHEN rn=1 THEN rating END) AS latest_rating,MAX(CASE WHEN rn=2 THEN rating END) AS middle_rating,MAX(CASE WHEN rn = 3 THEN rating END) AS earliest_rating FROM (SELECT employee_id,review_date,rating,ROW_NUMBER() OVER (PARTITION BY employee_id ORDER BY review_date DESC) AS rn FROM performance_reviews) x WHERE rn<=3 GROUP BY employee_id HAVING earliest_rating<middle_rating AND middle_rating<latest_rating) x JOIN Employees e ON x.employee_id=e.employee_id ORDER BY improvement_score DESC,e.name ASC;